"use client";
import { useState, useId } from "react";
import { ArrowDownUp, Download } from "lucide-react";
import { Button, Input, Select, Pagination, EmptyState, Card } from "@/components/ui/primitives";
export type Row = Record<string, string | number>;
export function downloadText(name: string, content: string, type = "application/json") {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function DataTable({
  title,
  rows,
  columns,
  pageSize = 5,
}: {
  title: string;
  rows: Row[];
  columns: { key: string; label: string }[];
  pageSize?: number;
}) {
  const [q, setQ] = useState("");
  const [sort, setSort] = useState(columns[0].key);
  const [desc, setDesc] = useState(false);
  const [status, setStatus] = useState("All");
  const [page, setPage] = useState(1);
  const filtered = rows
    .filter(
      (r) =>
        Object.values(r).join(" ").toLowerCase().includes(q.toLowerCase()) &&
        (status === "All" || r.status === status),
    )
    .sort((a, b) => {
      const av = a[sort],
        bv = b[sort];
      const n =
        typeof av === "number" && typeof bv === "number"
          ? av - bv
          : String(av).localeCompare(String(bv));
      return desc ? -n : n;
    });
  const pages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const current = Math.min(page, pages);
  const statuses = [
    "All",
    ...new Set(rows.map((r) => r.status).filter((s): s is string => typeof s === "string")),
  ];
  const exportCsv = () => {
    const cell = (v: unknown) =>
      '"' +
      String(v ?? "")
        .replace(/^[=+\-@]/, "'$&")
        .replaceAll('"', '""') +
      '"';
    downloadText(
      "table-export.csv",
      [
        columns.map((c) => cell(c.label)).join(","),
        ...filtered.map((r) => columns.map((c) => cell(r[c.key])).join(",")),
      ].join("\r\n"),
      "text/csv;charset=utf-8",
    );
  };
  return (
    <Card className="data-panel">
      <div className="spread">
        <h3>{title}</h3>
        <Button size="sm" variant="outline" onClick={exportCsv}>
          <Download size={14} />
          Export CSV
        </Button>
      </div>
      <div className="table-controls">
        <Input
          aria-label={"Search " + title}
          placeholder="Search records…"
          value={q}
          onChange={(e) => {
            setQ(e.target.value);
            setPage(1);
          }}
        />
        {statuses.length > 1 && (
          <Select
            label="Status"
            value={status}
            onChange={(e) => {
              setStatus(e.target.value);
              setPage(1);
            }}
            options={statuses.map((s) => ({ value: s, label: s }))}
          />
        )}
      </div>
      <div className="table-scroll">
        <table>
          <caption className="sr-only">
            {title}, {filtered.length} matching records
          </caption>
          <thead>
            <tr>
              {columns.map((c) => (
                <th
                  key={c.key}
                  aria-sort={sort === c.key ? (desc ? "descending" : "ascending") : "none"}
                >
                  <button
                    onClick={() => {
                      if (sort === c.key) setDesc(!desc);
                      else {
                        setSort(c.key);
                        setDesc(false);
                      }
                    }}
                  >
                    {c.label}
                    <ArrowDownUp size={13} />
                  </button>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.slice((current - 1) * pageSize, current * pageSize).map((row, i) => (
              <tr key={String(row.id || i)}>
                {columns.map((c) => (
                  <td key={c.key}>
                    {c.key === "status" ? (
                      <span
                        className={
                          "status-pill status-" +
                          String(row[c.key]).toLowerCase().replaceAll(" ", "-")
                        }
                      >
                        {row[c.key]}
                      </span>
                    ) : (
                      row[c.key]
                    )}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {!filtered.length && <EmptyState />}
      <Pagination page={current} pages={pages} onChange={setPage} />
    </Card>
  );
}
export function Chart({
  title,
  values = [32, 46, 41, 62, 58, 74, 69, 86, 80, 95, 88, 108],
  labels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
  type = "line",
}: {
  title: string;
  values?: number[];
  labels?: string[];
  type?: "line" | "bar" | "donut";
}) {
  const uid = useId().replaceAll(":", "");
  const max = Math.max(...values, 1);
  const pts = values
    .map((v, i) => 32 + i * (536 / Math.max(values.length - 1, 1)) + "," + (205 - (v / max) * 160))
    .join(" ");
  return (
    <div className={"chart chart-" + type}>
      <svg viewBox="0 0 600 245" role="img" aria-labelledby={uid}>
        <title id={uid}>
          {title + ": " + values.map((v, i) => (labels[i] || i + 1) + " " + v).join(", ")}
        </title>
        {type === "donut" ? (
          <g transform="translate(300 115) rotate(-90)">
            <circle r="80" fill="none" stroke="var(--muted)" strokeWidth="32" />
            {values.slice(0, 4).map((v, i) => {
              const total = values.slice(0, 4).reduce((a, b) => a + b, 0);
              return (
                <circle
                  key={i}
                  r="80"
                  fill="none"
                  stroke={"var(--chart-" + (i + 1) + ")"}
                  strokeWidth="32"
                  strokeDasharray={(v / total) * 502 + " 502"}
                  strokeDashoffset={(-values.slice(0, i).reduce((a, b) => a + b, 0) / total) * 502}
                />
              );
            })}
          </g>
        ) : (
          <>
            {[45, 85, 125, 165, 205].map((y) => (
              <line
                key={y}
                x1="32"
                y1={y}
                x2="568"
                y2={y}
                stroke="var(--border)"
                opacity=".3"
                strokeDasharray="4 5"
              />
            ))}
            {type === "line" ? (
              <>
                <polygon points={"32,205 " + pts + " 568,205"} fill="var(--primary)" opacity=".1" />
                <polyline
                  points={pts}
                  fill="none"
                  stroke="var(--primary)"
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </>
            ) : (
              values.map((v, i) => (
                <rect
                  key={i}
                  x={32 + i * (536 / values.length)}
                  y={205 - (v / max) * 160}
                  width={Math.max(8, 536 / values.length - 12)}
                  height={(v / max) * 160}
                  rx="4"
                  fill={"var(--chart-" + ((i % 2) + 1) + ")"}
                />
              ))
            )}
            {labels.slice(0, values.length).map((l, i) =>
              i % 2 === 0 ? (
                <text
                  key={i}
                  x={32 + (i * 536) / Math.max(values.length - 1, 1)}
                  y="232"
                  fill="var(--muted-foreground)"
                  fontSize="12"
                  textAnchor="middle"
                >
                  {l}
                </text>
              ) : null,
            )}
          </>
        )}
      </svg>
      <details>
        <summary>View chart data</summary>
        <table>
          <caption>{title}</caption>
          <tbody>
            {values.map((v, i) => (
              <tr key={i}>
                <th>{labels[i] || "Series " + (i + 1)}</th>
                <td>{v}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>
    </div>
  );
}
export function MetricCards({
  items,
}: {
  items: { label: string; value: string; change: string }[];
}) {
  return (
    <div className="metric-cards">
      {items.map((i) => (
        <Card key={i.label} variant="metric">
          <span className="muted">{i.label}</span>
          <strong>{i.value}</strong>
          <small>{i.change}</small>
        </Card>
      ))}
    </div>
  );
}

"use client";
import { useState, type ReactNode } from "react";
import {
  Layers,
  LayoutDashboard,
  BarChart3,
  Users,
  Settings,
  PanelLeftClose,
  Menu,
  Bell,
  Folder,
  Search,
} from "lucide-react";
import {
  Button,
  Avatar,
  DropdownMenu,
  Dialog,
  Input,
  Badge,
  CommandMenu,
} from "@/components/ui/primitives";
import type { SectionProps } from "@/components/sections/shared";
export function ShellSection({
  content,
  variant,
  children,
  className = "",
  embedded = false,
}: SectionProps & { children?: ReactNode; embedded?: boolean }) {
  const ContentRoot = embedded ? "div" : "main";
  const [collapsed, setCollapsed] = useState(false);
  const [mobile, setMobile] = useState(false);
  const [panel, setPanel] = useState<string | null>(null);
  const [name, setName] = useState("Alex Morgan");
  const links = [
    ["Overview", LayoutDashboard, "#app-main"],
    ["Activity", BarChart3, "#app-activity"],
    ["People", Users, "#app-main"],
    ["Projects", Folder, "#app-main"],
  ] as const;
  return (
    <div
      className={
        "dashboard-shell shell-" +
        variant +
        (collapsed ? " is-collapsed" : "") +
        (mobile ? " mobile-open" : "") +
        " " +
        className
      }
    >
      <aside className="app-sidebar">
        <a href="#top" className="brand">
          <Layers size={24} />
          <span>{content.title}</span>
        </a>
        {["workspace", "dual", "sidebar"].includes(variant) && (
          <DropdownMenu
            label="Design workspace"
            items={["Design workspace", "Operations", "Personal"].map((label) => ({
              label,
              onSelect: () => setPanel(label),
            }))}
          />
        )}
        <div className="sidebar-label">WORKSPACE</div>
        <nav aria-label="Application navigation">
          {links.map(([label, Icon, href], i) => (
            <a
              className={i === 0 ? "active" : ""}
              key={label}
              href={href}
              onClick={() => setMobile(false)}
              title={label}
            >
              <Icon size={19} />
              <span>{label}</span>
              {i === 3 && <Badge>8</Badge>}
            </a>
          ))}
          <button onClick={() => setPanel("Settings")} title="Settings">
            <Settings size={19} />
            <span>Settings</span>
          </button>
        </nav>
        {variant === "dual" && (
          <div className="sidebar-projects">
            <span className="sidebar-label">YOUR TEAMS</span>
            <button onClick={() => setPanel("Product team")}>Product team</button>
            <button onClick={() => setPanel("Operations team")}>Operations team</button>
          </div>
        )}
        <div className="sidebar-account">
          <Avatar name={name} />
          <div>
            <strong>{name}</strong>
            <small>Workspace admin</small>
          </div>
        </div>
      </aside>
      <div className="app-main">
        <header className="app-topbar">
          <Button
            variant="ghost"
            size="icon"
            aria-label="Toggle sidebar"
            onClick={() => {
              setCollapsed(!collapsed);
              setMobile(!mobile);
            }}
          >
            {collapsed ? <Menu size={19} /> : <PanelLeftClose size={19} />}
          </Button>
          <span className="muted">Workspace / Overview</span>
          <div className="topbar-actions">
            <CommandMenu items={links.map(([label, , href]) => ({ label, href }))} />
            <Button
              variant="ghost"
              size="icon"
              aria-label="Notifications"
              onClick={() => setPanel("Notifications")}
            >
              <Bell size={19} />
            </Button>
            <Avatar name={name} />
          </div>
        </header>
        {variant === "command" && (
          <div className="command-bar">
            <Search size={17} />
            <a href="#app-main">Fleet overview</a>
            <a href="#app-activity">Dispatch activity</a>
            <span>Local sample data</span>
          </div>
        )}
        <ContentRoot id="app-main" className="dashboard-content">
          {children}
        </ContentRoot>
      </div>
      {variant === "split" && (
        <aside className="app-context">
          <h3>Today at a glance</h3>
          <p>3 upcoming events</p>
          <p>2 requests to review</p>
          <Button variant="outline" onClick={() => setPanel("Daily briefing")}>
            Open briefing
          </Button>
        </aside>
      )}
      <Dialog
        title={panel || "Workspace"}
        description="Local workspace controls."
        open={!!panel}
        onOpenChange={(o) => {
          if (!o) setPanel(null);
        }}
      >
        {panel === "Settings" ? (
          <form
            onSubmit={(e) => {
              e.preventDefault();
              setPanel(null);
            }}
          >
            <label className="ui-field">
              Display name
              <Input value={name} onChange={(e) => setName(e.target.value)} required />
            </label>
            <Button type="submit">Save profile</Button>
          </form>
        ) : panel === "Notifications" ? (
          <ul className="notification-list">
            <li>Your weekly report is ready.</li>
            <li>Jordan completed the launch checklist.</li>
            <li>Two requests are waiting for review.</li>
          </ul>
        ) : (
          <p>
            {panel} is ready to explore. These sample workspaces demonstrate navigation without a
            backend.
          </p>
        )}
      </Dialog>
    </div>
  );
}

"use client";
import { useState, createContext, useContext } from "react";
import { Plus, Clock, Truck, Building2, Download } from "lucide-react";
import {
  Button,
  Card,
  Input,
  Select,
  Badge,
  Avatar,
  Dialog,
  Alert,
  Progress,
  Switch,
  EmptyState,
} from "@/components/ui/primitives";
import { DataTable, Chart, MetricCards, downloadText, type Row } from "./data";
import { ReorderList } from "@/components/motion/primitives";
import type { SectionProps } from "@/components/sections/shared";
const ReportPeriod = createContext(30);
const people = [
  "Alex Morgan",
  "Jordan Lee",
  "Sam Rivera",
  "Taylor Reed",
  "Jamie Parker",
  "Casey Chen",
  "Riley Brooks",
  "Avery Kim",
];
const commonMetrics = [
  { label: "Total revenue", value: "$48,295", change: "+12.8% from last month" },
  { label: "Active customers", value: "2,420", change: "+8.2% from last month" },
  { label: "Projects in progress", value: "32", change: "6 launching this week" },
  { label: "Completion rate", value: "94.2%", change: "+3.4% from last month" },
];
const activity = [
  ["Jordan Lee", "Completed the launch checklist", "12 minutes ago"],
  ["Sam Rivera", "Added feedback to the dashboard review", "38 minutes ago"],
  ["Taylor Reed", "Updated the project timeline", "1 hour ago"],
  ["Alex Morgan", "Invited Casey to the workspace", "2 hours ago"],
];
function Activity() {
  return (
    <Card>
      <h3>Recent activity</h3>
      <ol className="activity-list">
        {activity.map(([name, event, time]) => (
          <li key={name}>
            <Avatar name={name} />
            <div>
              <strong>{name}</strong>
              <p>{event}</p>
              <small>{time}</small>
            </div>
          </li>
        ))}
      </ol>
    </Card>
  );
}
function ChartPanel({
  title = "Revenue over time",
  type = "line",
  factor = 1,
}: {
  title?: string;
  type?: "line" | "bar" | "donut";
  factor?: number;
}) {
  const days = useContext(ReportPeriod);
  return (
    <Card>
      <div className="spread">
        <h3>{title}</h3>
        <Badge>Sample data</Badge>
      </div>
      <Chart
        title={title}
        type={type}
        values={[32, 46, 41, 62, 58, 74, 69, 86, 80, 95, 88, 108].map((v) =>
          Math.round((v * factor * days) / 30),
        )}
      />
    </Card>
  );
}
function Overview() {
  return (
    <>
      <MetricCards items={commonMetrics} />
      <div className="dashboard-grid">
        <ChartPanel />
        <Card>
          <h3>Project health</h3>
          <Progress value={82} label="Website redesign" />
          <Progress value={64} label="Mobile experience" />
          <Progress value={91} label="Design system" />
          <Progress value={38} label="Customer portal" />
        </Card>
      </div>
      <DataTable
        title="Recent projects"
        rows={people.map((name, i) => ({
          id: i,
          name: [
            "Website redesign",
            "Mobile onboarding",
            "Design system",
            "Customer portal",
            "Analytics update",
            "Billing flow",
            "Documentation",
            "Brand refresh",
          ][i],
          owner: name,
          status: i % 3 === 0 ? "In progress" : i % 3 === 1 ? "Review" : "Completed",
          due: "Oct " + (12 + i),
        }))}
        columns={[
          { key: "name", label: "Project" },
          { key: "owner", label: "Owner" },
          { key: "status", label: "Status" },
          { key: "due", label: "Due date" },
        ]}
      />
    </>
  );
}
function Analytics() {
  const [channel, setChannel] = useState("All channels");
  const factor = channel === "Organic" ? 0.7 : channel === "Referral" ? 0.3 : 1;
  return (
    <>
      <div className="analytics-summary">
        <div>
          <span className="eyebrow">AUDIENCE GROWTH</span>
          <strong>{Math.round(128420 * factor).toLocaleString("en-US")}</strong>
          <p>Visitors in the selected period</p>
        </div>
        <Select
          label="Channel"
          value={channel}
          onChange={(e) => setChannel(e.target.value)}
          options={["All channels", "Organic", "Referral"].map((x) => ({ value: x, label: x }))}
        />
      </div>
      <div className="dashboard-grid">
        <ChartPanel title="Visitor trends" factor={factor} />
        <ChartPanel title="Traffic sources" type="donut" factor={factor} />
      </div>
      <div className="dashboard-grid equal">
        <Card>
          <h3>Conversion funnel</h3>
          {[
            ["Visitors", 100],
            ["Product views", 72],
            ["Signups", 28],
            ["Activated", 18],
          ].map(([label, value]) => (
            <Progress key={label} label={String(label)} value={Number(value)} />
          ))}
        </Card>
        <DataTable
          title="Top pages"
          rows={[
            { page: "/", views: Math.round(42800 * factor), conversion: "4.8%" },
            { page: "/product", views: Math.round(18640 * factor), conversion: "6.2%" },
            { page: "/pricing", views: Math.round(12920 * factor), conversion: "8.1%" },
            { page: "/blog", views: Math.round(8400 * factor), conversion: "2.4%" },
          ]}
          columns={[
            { key: "page", label: "Page" },
            { key: "views", label: "Views" },
            { key: "conversion", label: "Conversion" },
          ]}
        />
      </div>
    </>
  );
}
function Pipeline() {
  const [deals, setDeals] = useState([
    { name: "Northstar Studio", value: 12400, stage: "Lead", owner: "Alex Morgan" },
    { name: "Fieldwork Inc.", value: 8600, stage: "Qualified", owner: "Jordan Lee" },
    { name: "Forma Design", value: 24000, stage: "Proposal", owner: "Sam Rivera" },
    { name: "Layer Labs", value: 16800, stage: "Won", owner: "Taylor Reed" },
    { name: "Acme Partners", value: 6200, stage: "Lead", owner: "Jamie Parker" },
  ]);
  const [open, setOpen] = useState(false);
  const stages = ["Lead", "Qualified", "Proposal", "Won"];
  return (
    <>
      <MetricCards
        items={[
          {
            label: "Pipeline value",
            value: "$" + deals.reduce((a, d) => a + d.value, 0).toLocaleString("en-US"),
            change: deals.length + " active opportunities",
          },
          { label: "Won this month", value: "$16,800", change: "2 new relationships" },
          { label: "Win rate", value: "32%", change: "+4% from last month" },
        ]}
      />
      <div className="spread">
        <h2>Deal pipeline</h2>
        <Button onClick={() => setOpen(true)}>
          <Plus size={16} />
          Add opportunity
        </Button>
      </div>
      <div className="kanban-board">
        {stages.map((stage) => (
          <div className="kanban-column" key={stage}>
            <h3>
              {stage}
              <Badge>{deals.filter((d) => d.stage === stage).length}</Badge>
            </h3>
            {deals
              .filter((d) => d.stage === stage)
              .map((d) => (
                <Card key={d.name}>
                  <h4>{d.name}</h4>
                  <strong>&#36;{d.value.toLocaleString("en-US")}</strong>
                  <p>{d.owner}</p>
                  <Select
                    label="Move to"
                    value={d.stage}
                    onChange={(e) =>
                      setDeals(
                        deals.map((x) => (x.name === d.name ? { ...x, stage: e.target.value } : x)),
                      )
                    }
                    options={stages.map((x) => ({ value: x, label: x }))}
                  />
                </Card>
              ))}
          </div>
        ))}
      </div>
      <Dialog title="New opportunity" open={open} onOpenChange={setOpen}>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            const data = new FormData(e.currentTarget);
            setDeals([
              ...deals,
              {
                name: String(data.get("name")),
                value: Number(data.get("value")),
                stage: "Lead",
                owner: "Alex Morgan",
              },
            ]);
            setOpen(false);
          }}
        >
          <label className="ui-field">
            Company
            <Input name="name" required />
          </label>
          <label className="ui-field">
            Value ($)
            <Input type="number" name="value" min={0} required />
          </label>
          <Button type="submit">Create opportunity</Button>
        </form>
      </Dialog>
    </>
  );
}
function People() {
  const [approved, setApproved] = useState<string[]>([]);
  return (
    <>
      <MetricCards
        items={[
          { label: "Team members", value: "148", change: "8 joined this month" },
          { label: "On leave today", value: "6", change: "4% of the team" },
          { label: "Open roles", value: "12", change: "3 final interviews" },
          { label: "Team satisfaction", value: "4.8 / 5", change: "From 126 responses" },
        ]}
      />
      <div className="dashboard-grid">
        <DataTable
          title="People directory"
          rows={people.map((name, i) => ({
            id: i,
            name,
            department: ["Product", "Engineering", "Design", "Operations"][i % 4],
            status: i === 2 ? "On leave" : "Active",
            location: i % 2 ? "Remote" : "London",
          }))}
          columns={[
            { key: "name", label: "Name" },
            { key: "department", label: "Department" },
            { key: "status", label: "Status" },
            { key: "location", label: "Location" },
          ]}
        />
        <Card>
          <h3>Leave requests</h3>
          {["Jamie Parker", "Casey Chen"].map((name, i) => (
            <div className="request-row" key={name}>
              <Avatar name={name} />
              <div>
                <strong>{name}</strong>
                <p>
                  Oct {14 + i}–{16 + i} · Annual leave
                </p>
              </div>
              <Button
                size="sm"
                variant="outline"
                disabled={approved.includes(name)}
                onClick={() => setApproved([...approved, name])}
              >
                {approved.includes(name) ? "Approved" : "Approve"}
              </Button>
            </div>
          ))}
          <h3>Upcoming milestones</h3>
          <p>Sam Rivera · 3-year anniversary</p>
          <p>Jordan Lee · Birthday this Friday</p>
        </Card>
      </div>
    </>
  );
}
function Finance() {
