        <nav aria-label="Documentation topics">
          {guides
            .filter((g) => (g.title + " " + g.description).toLowerCase().includes(q.toLowerCase()))
            .map((g) => (
              <button
                key={g.id}
                aria-current={selected === g.id ? "page" : undefined}
                onClick={() => {
                  setSelected(g.id);
                  setCopied(false);
                }}
              >
                <BookOpen size={16} />
                {g.title}
              </button>
            ))}
        </nav>
      </aside>
      <article>
