import type { MotionProfile } from "@/registry/schema";
export function motionSettings(profile: MotionProfile, reduced: boolean) {
  const disabled = reduced || profile.id === "no-motion";
  return {
    disabled,
    initial: disabled
      ? { opacity: 1, x: 0, y: 0, scale: 1 }
      : {
          opacity: 0,
          x: profile.pattern === "slide" ? profile.distance / 3 : 0,
          y: profile.pattern === "fade" ? 0 : profile.distance,
          scale: profile.scale,
        },
    visible: { opacity: 1, x: 0, y: 0, scale: 1 },
    transition: disabled
      ? { duration: 0 }
      : profile.spring
        ? { type: "spring" as const, ...profile.spring }
        : { duration: profile.duration, ease: profile.ease },
    hover: disabled ? 1 : profile.hover,
    stagger: disabled ? 0 : profile.stagger,
  };
}

import { rawItems } from "@/registry/catalog";
import {
  registryItemSchema,
  designConfigSchema,
  type RegistryItem,
  type Template,
  type DesignInput,
} from "@/registry/schema";
export const items: RegistryItem[] = rawItems.map((item) => registryItemSchema.parse(item));
export const templates = items.filter((i): i is Template => i.kind === "template");
export const themes = items.filter((i) => i.kind === "theme");
export const styles = items.filter((i) => i.kind === "style");
export const motions = items.filter((i) => i.kind === "motion");
export const sections = items.filter((i) => i.kind === "section");
export const components = items.filter((i) => i.kind === "component");
export function lookup<K extends RegistryItem["kind"]>(
  id: string,
  kind: K,
): Extract<RegistryItem, { kind: K }> {
  const item = items.find((i) => i.id === id && i.kind === kind);
  if (!item)
    throw new Error(
      "Unknown " + kind + ' "' + id + '". Run pnpm registry:list --kind ' + kind + ".",
    );
  return item as Extract<RegistryItem, { kind: K }>;
}
export function resolveDesign(input: DesignInput) {
  const config = designConfigSchema.parse(input);
  const template = lookup(config.template, "template");
  const style = lookup(config.style || template.defaultStyleId, "style");
  const theme = lookup(config.theme || template.defaultThemeId, "theme");
  const motion = lookup(config.motion || template.defaultMotionId, "motion");
  if (!template.compatibleStyles.includes(style.id))
    throw new Error("Style " + style.id + " is incompatible with " + template.id);
  if (!template.supportedThemes.includes(theme.id))
    throw new Error("Theme " + theme.id + " is incompatible with " + template.id);
  if (!template.supportedMotion.includes(motion.id))
    throw new Error("Motion " + motion.id + " is incompatible with " + template.id);
  for (const [group, id] of Object.entries(config.overrides)) {
    const section = lookup(id, "section");
    if (section.group !== group)
      throw new Error("Override " + group + " requires a " + group + " section; received " + id);
    if (!template.sections.some((s) => lookup(s.id, "section").group === group))
      throw new Error(template.id + " has no " + group + " slot to override.");
  }
  for (const key of Object.keys(config.content))
    if (!template.sections.some((s) => s.key === key))
      throw new Error("Unknown content slot " + key + " in " + template.id);
  const resolvedSections = template.sections.map((section) => {
    const group = lookup(section.id, "section").group;
    return {
      ...section,
      id: config.overrides[group] || section.id,
      content: config.content[section.key] || section.content,
    };
  });
  return {
    template,
    style,
    theme,
    motion,
    sections: resolvedSections,
    config: {
      ...config,
      style: style.id,
      theme: theme.id,
      motion: motion.id,
      mode: config.mode || template.defaultMode,
    },
  };
}
export function validateReferences(catalog: RegistryItem[] = items) {
  const errors: string[] = [];
  const seen = new Set<string>();
  for (const item of catalog) {
    if (seen.has(item.id)) errors.push("Duplicate ID: " + item.id);
    seen.add(item.id);
  }
  const has = (id: string, kind: string, owner: string) => {
    if (!catalog.some((i) => i.id === id && i.kind === kind))
      errors.push(owner + ": missing " + kind + " reference " + id);
  };
  for (const item of catalog) {
    if (item.kind === "template") {
      for (const id of item.compatibleStyles) has(id, "style", item.id);
      for (const id of item.supportedThemes) has(id, "theme", item.id);
      for (const id of item.supportedMotion) has(id, "motion", item.id);
      for (const id of item.components) has(id, "component", item.id);
      for (const section of item.sections) has(section.id, "section", item.id);
      if (new Set(item.sections.map((s) => s.key)).size !== item.sections.length)
        errors.push(item.id + ": duplicate section keys");
      for (const [id, allowed, kind] of [
        [item.defaultStyleId, item.compatibleStyles, "style"],
        [item.defaultThemeId, item.supportedThemes, "theme"],
        [item.defaultMotionId, item.supportedMotion, "motion"],
      ] as const) {
        has(id, kind, item.id);
        if (!allowed.includes(id)) errors.push(item.id + ": invalid default " + kind + " " + id);
      }
    }
    if (item.kind === "section") for (const id of item.components) has(id, "component", item.id);
    if (item.kind === "style") has(item.defaultMotionId, "motion", item.id);
  }
  return errors;
}

import { resolveDesign, lookup } from "@/lib/registry";
import { themeVariables, styleVariables, layoutVariables } from "@/lib/theme";
import { sectionMap } from "@/lib/section-map";
import { ThemeScope } from "@/components/ui/theme-scope";
import { MotionProvider, Reveal } from "@/components/motion/primitives";
import { ShellSection } from "@/components/dashboards/shells";
import type { DesignInput } from "@/registry/schema";
export function TemplateRenderer({
  config,
  className = "",
  style: containerStyle,
  embedded = false,
}: {
  config: DesignInput;
  className?: string;
  style?: React.CSSProperties;
  embedded?: boolean;
}) {
  const design = resolveDesign(config);
  const ContentRoot = embedded ? "div" : "main";
  const { template, style, theme, motion } = design;
  const shell = design.sections.find((s) => lookup(s.id, "section").group === "shell");
  const content = design.sections
    .filter((s) => lookup(s.id, "section").group !== "shell")
    .map((section, index) => {
      const meta = lookup(section.id, "section");
      const Component = sectionMap[section.id];
      if (!Component) throw new Error("No implementation for " + section.id);
      return (
        <div key={section.key} id={section.key} data-section-id={section.id}>
          {index === 2 && <span id="content" />}
          {meta.group === "features" && <span id="features" />}
          {["navbar", "hero", "footer"].includes(meta.group) ? (
            <Component variant={meta.variant} content={section.content} />
          ) : (
            <Reveal>
              <Component variant={meta.variant} content={section.content} />
            </Reveal>
          )}
        </div>
      );
    });
  const variables = {
    ...themeVariables(theme, design.config.mode),
    ...styleVariables(style),
    ...layoutVariables(design.config.layout),
    "--preview-min-height": embedded ? "0px" : "100dvh",
    "--motion-duration": motion.duration + "s",
  } as React.CSSProperties;
  return (
    <ThemeScope variables={variables}>
      <div
        id="top"
        className={"factory-preview " + className}
        style={{ ...variables, ...containerStyle }}
        data-template={template.id}
        data-style={style.id}
        data-theme={theme.id}
        data-mode={design.config.mode}
        data-motion={motion.id}
        data-surface={style.surface}
        data-decoration={style.decoration}
        data-button={style.button}
        data-input={style.input}
        data-background={style.background}
        data-card={design.config.card}
      >
        <MotionProvider profile={motion}>
          {shell ? (
            <ShellSection
              embedded={embedded}
              variant={lookup(shell.id, "section").variant}
              content={shell.content}
            >
              {content}
            </ShellSection>
          ) : (
            <ContentRoot>{content}</ContentRoot>
          )}
        </MotionProvider>
      </div>
    </ThemeScope>
  );
}

import type { CSSProperties } from "react";
import type { Theme, StyleProfile, DesignInput } from "@/registry/schema";
export function layoutVariables(layout: DesignInput["layout"]): CSSProperties {
  return {
    ...(layout?.contentWidth !== undefined && { "--content-width": layout.contentWidth + "px" }),
    ...(layout?.density !== undefined && { "--density": layout.density }),
    ...(layout?.radius !== undefined && { "--radius": layout.radius + "px" }),
  } as CSSProperties;
}
export function themeVariables(theme: Theme, mode: "light" | "dark"): CSSProperties {
  return Object.fromEntries([
    ...Object.entries(theme[mode]).map(([k, v]) => ["--" + k, v]),
    ["--gradient-hero", theme.gradients.hero],
    ["--gradient-accent", theme.gradients.accent],
    ["colorScheme", mode],
  ]) as CSSProperties;
}
export function styleVariables(style: StyleProfile): CSSProperties {
  return {
    "--font-heading": style.headingFont,
    "--font-body": style.bodyFont,
    "--heading-weight": style.headingWeight,
    "--body-weight": style.bodyWeight,
    "--heading-scale": style.headingScale,
    "--density": style.density,
    "--content-width": style.maxWidth + "px",
    "--space": style.spacing + "px",
    "--border-width": style.borderWidth + "px",
    "--border-style": style.borderStyle,
    "--radius": style.radius + "px",
    "--elevation": style.shadow,
  } as CSSProperties;
}
export function contrastRatio(a: string, b: string) {
  const luminance = (hex: string) => {
    const channels = [1, 3, 5]
      .map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
      .map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
    return channels[0] * 0.2126 + channels[1] * 0.7152 + channels[2] * 0.0722;
  };
  const x = luminance(a),
    y = luminance(b);
  return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
}

