.border-glow {
  position: relative;
  isolation: isolate;
  padding: 2px;
  border-radius: var(--radius);
  width: 100%;
  min-width: 0;
}
.effect-edge {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
  z-index: -1;
  pointer-events: none;
  background: var(--border);
}
.effect-edge::before {
  content: "";
  position: absolute;
  inset: -150%;
  background: conic-gradient(
    from 0deg,
    transparent 45%,
    var(--primary),
    var(--chart-2),
    transparent 85%
  );
  opacity: var(--effect-strength);
  animation: effect-orbit var(--effect-duration) linear infinite;
}
.effect-edge::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: max(0px, calc(var(--radius) - 2px));
  background: var(--card);
}
.border-glow-content {
  padding: clamp(16px, 4cqi, 32px);
  color: var(--card-foreground);
}
.border-glow-content > * + * {
  margin-top: 16px;
}
.status-orb-wrap {
  display: inline-grid;
  place-items: center;
  max-width: 100%;
}
.status-orb {
  display: inline-grid;
  width: var(--orb-size);
  max-width: 100%;
  aspect-ratio: 1;
  border-radius: 50%;
  overflow: hidden;
  position: relative;
  isolation: isolate;
  background: var(--primary);
  box-shadow:
    inset 0 -6px 15px #00000030,
    0 0 28px color-mix(in srgb, var(--primary) 18%, transparent);
}
.status-orb > span {
  position: absolute;
  inset: -30%;
  border-radius: 42%;
  background: conic-gradient(var(--primary), var(--chart-2), var(--accent), var(--primary));
  animation: effect-orbit var(--effect-duration) linear infinite;
}
.status-orb::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(circle at 30% 22%, #ffffffaa, transparent 40%, #00000044);
}
.orb-listening > span {
  animation-direction: reverse;
  border-radius: 30%;
}
.orb-idle {
  opacity: 0.65;
}
.orb-complete {
  --primary: var(--success);
  --chart-2: var(--success);
}
.orb-error {
  --primary: var(--destructive);
  --chart-2: var(--destructive);
}
.metallic-button {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--foreground);
  color: var(--background);
  border: 1px solid var(--foreground);
  box-shadow:
    inset 0 1px 0 #ffffff70,
    inset 0 -2px 0 #00000030;
}
.metallic-button::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  background: linear-gradient(115deg, transparent 20%, #ffffff35 45%, transparent 65%);
  transform: translateX(-100%);
}
.metallic-button:is(:hover, :focus-visible)::before {
  animation: effect-sheen 1.2s ease-out;
}
.border-glow[data-active="false"] .effect-edge::before,
.status-orb[data-active="false"] > span {
  animation-play-state: paused;
}
.metallic-button[data-active="false"]::before {
  animation: none;
}
@keyframes effect-orbit {
  to {
    transform: rotate(360deg);
  }
}
@keyframes effect-sheen {
  to {
    transform: translateX(100%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .effect-edge::before,
  .status-orb > span,
  .metallic-button::before {
    animation: none !important;
  }
}

@import "tailwindcss";
@import "./effects.css";
@import "./mobile.css";
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-card: var(--card);
  --color-border: var(--border);
  --color-ring: var(--ring);
  --color-card-foreground: var(--card-foreground);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-input: var(--input);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-destructive: var(--destructive);
  --color-info: var(--info);
  --color-link: var(--link);
  --color-selected: var(--selected);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --font-sans: var(--font-body);
  --radius-lg: var(--radius);
}
:root {
  --background: #f8f9fb;
  --foreground: #192124;
  --primary: #d4f56a;
  --primary-foreground: #1d2912;
  --secondary: #e9edf0;
  --secondary-foreground: #243034;
  --accent: #eef6d7;
  --accent-foreground: #273413;
  --card: #fff;
  --card-foreground: #192124;
  --muted: #edf0f3;
  --muted-foreground: #5f6b70;
  --border: #cbd1d5;
  --input: #8a969e;
  --ring: #506b12;
  --success: #167348;
  --warning: #916007;
  --destructive: #b32e3d;
  --info: #245d91;
  --link: #405a12;
  --selected: #e9f2d4;
  --sidebar: #181d20;
  --sidebar-foreground: #e2e7e9;
  --sidebar-accent: #2a3238;
  --chart-1: #547d26;
  --chart-2: #3b8793;
  --chart-3: #8e70b5;
  --chart-4: #b48b3f;
  --chart-5: #b56373;
  --radius: 12px;
  --border-width: 1px;
  --border-style: solid;
  --space: 24px;
  --density: 1;
  --content-width: 1180px;
  --font-heading: Arial, Helvetica, sans-serif;
  --font-body: Arial, Helvetica, sans-serif;
  --heading-weight: 650;
  --body-weight: 400;
  --heading-scale: 1;
  --media-foreground: #ffffff;
  --media-background: #17212a;
  --elevation: none;
  --gradient-hero: linear-gradient(135deg, var(--background), var(--accent));
  --gradient-accent: linear-gradient(120deg, var(--primary), var(--chart-2));
  --motion-duration: 0.2s;
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
}
button,
input,
select,
textarea {
  font: inherit;
}
button,
a,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}
button,
a {
  touch-action: manipulation;
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
a {
  color: inherit;
  text-decoration: none;
}
button {
  color: inherit;
}
h1,
h2,
h3,
h4,
p {
  margin: 0;
}
h1,
h2,
h3,
h4 {
  font-family: var(--font-heading);
  font-weight: var(--heading-weight);
  line-height: 1.15;
  letter-spacing: -0.035em;
}
h1 {
  font-size: clamp(2.25rem, 5.5cqi, 4.5rem);
}
h2 {
  font-size: clamp(1.75rem, 3cqi, 2.7rem);
}
h3 {
  font-size: 1.2rem;
  letter-spacing: -0.02em;
}
h4 {
  font-size: 1rem;
}
p {
  color: var(--muted-foreground);
  line-height: 1.7;
}
svg {
  flex-shrink: 0;
}
button svg,
a svg {
  vertical-align: middle;
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible,
[tabindex]:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
}
::selection {
  background: var(--selected);
}
ul,
ol {
  padding: 0;
}
img {
  max-width: 100%;
}
small {
  font-size: 0.8125rem;
}
pre {
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
summary {
  cursor: pointer;
}
table {
  border-collapse: collapse;
  width: 100%;
  font-size: 0.875rem;
}
th,
td {
  padding: 14px 16px;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
th {
  font-weight: 600;
  color: var(--muted-foreground);
}
caption {
  text-align: left;
  padding: 12px;
  font-weight: 600;
}
table button {
  border: 0;
  background: none;
  display: flex;
  gap: 6px;
  align-items: center;
  padding: 0;
  text-align: left;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.skip-link {
  position: fixed;
  top: -100px;
  left: 16px;
  background: var(--card);
  padding: 12px 20px;
  z-index: 100;
}
.skip-link:focus {
  top: 12px;
}
.ui-button {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 18px;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) * 0.7);
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.35;
  white-space: normal;
  max-width: 100%;
  overflow-wrap: anywhere;
  transition:
    background var(--motion-duration),
    box-shadow var(--motion-duration),
    transform var(--motion-duration);
}
.button-primary {
  background: var(--primary);
  color: var(--primary-foreground);
}
.button-secondary {
  background: var(--secondary);
  color: var(--secondary-foreground);
}
.button-outline {
  background: transparent;
  border-color: var(--border);
  color: var(--foreground);
}
.button-ghost {
  background: transparent;
  color: var(--foreground);
}
.button-destructive {
  background: var(--destructive);
  color: var(--background);
}
.button-sm {
  min-height: 36px;
  padding: 7px 12px;
  font-size: 0.8125rem;
}
.button-icon {
  padding: 10px;
  width: 44px;
  min-width: 44px;
}
.ui-button:hover {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 12%, transparent);
}
.button-ghost:hover,
.button-outline:hover {
  background: var(--muted);
}
.ui-input {
  display: block;
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--input);
  border-radius: calc(var(--radius) * 0.65);
  background: var(--card);
  color: var(--foreground);
  font-size: 0.875rem;
}
.ui-input::placeholder {
  color: var(--muted-foreground);
}
.ui-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 0.8125rem;
  font-weight: 500;
  margin-bottom: 16px;
}
.ui-field > span,
.ui-label {
  color: var(--muted-foreground);
}
.check-label {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.875rem;
  min-height: 44px;
}
.check-label input {
  width: 18px;
  height: 18px;
  accent-color: var(--primary);
}
.ui-switch {
  width: 42px;
  height: 25px;
  background: var(--muted);
  border: 1px solid var(--border);
  border-radius: 30px;
  padding: 3px;
}
.ui-switch[data-state="checked"] {
  background: var(--primary);
}
.switch-thumb {
  display: block;
  width: 17px;
  height: 17px;
  background: var(--foreground);
  border-radius: 50%;
  transition: transform var(--motion-duration);
}
.switch-thumb[data-state="checked"] {
  transform: translateX(16px);
  background: var(--primary-foreground);
}
.ui-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border: 1px solid color-mix(in srgb, var(--border) 60%, transparent);
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 500;
  line-height: 1.4;
  background: var(--muted);
  color: var(--foreground);
  white-space: nowrap;
}
.ui-avatar {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-foreground);
  font-size: 0.75rem;
  font-weight: 700;
  border: 1px solid var(--border);
}
.ui-card {
  padding: var(--space);
  background: var(--card);
  color: var(--card-foreground);
  border: var(--border-width) var(--border-style) color-mix(in srgb, var(--border) 65%, transparent);
  border-radius: var(--radius);
  box-shadow: var(--elevation);
  min-width: 0;
}
.ui-card > h3 {
  margin-bottom: 12px;
}
.ui-card > p {
  margin: 10px 0;
}
.ui-card .ui-button {
  margin-top: 12px;
}
.card-elevated {
  box-shadow: 0 12px 30px #00000012;
}
.card-outline {
  border: 2px solid var(--primary);
  background: transparent;
}
.card-metric {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.card-metric > strong {
  font-size: 2rem;
  letter-spacing: -0.04em;
}
.card-metric > small {
  color: var(--success);
}
.card-image {
  background: var(--gradient-hero);
  min-height: 180px;
  display: flex;
  flex-direction: column;
  justify-content: end;
}
.card-horizontal {
  display: flex;
  gap: 24px;
  align-items: center;
}
.card-interactive {
  transition:
    transform var(--motion-duration),
    box-shadow var(--motion-duration);
}
.card-interactive:hover,
.card-interactive:focus-within {
  transform: translateY(-3px);
  box-shadow: 0 12px 24px #00000014;
}
.card-accent {
  border-left: 5px solid var(--primary);
  background: var(--accent);
}
.ui-separator {
  border: 0;
  border-top: 1px solid var(--border);
  margin: 24px 0;
}
.ui-link,
.text-link {
  color: var(--link);
  text-decoration: underline;
  text-underline-offset: 4px;
}
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.875rem;
