.ui-tooltip,
.ui-popover,
.ui-menu {
  background: var(--card);
  color: var(--foreground);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  box-shadow: 0 10px 35px #00000020;
  z-index: 70;
