.ui-menu [role="menuitem"] {
  padding: 9px 14px;
  border-radius: 5px;
  font-size: 0.875rem;
  cursor: pointer;
  outline: none;
}
.ui-menu [data-highlighted] {
  background: var(--selected);
}
.dialog-overlay {
  position: fixed;
  inset: 0;
  background: #10162088;
  z-index: 80;
}
.ui-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
