  max-height: 88dvh;
  overflow: auto;
  background: var(--card);
  color: var(--foreground);
  padding: 32px;
  border-radius: 16px;
  border: 1px solid var(--border);
  box-shadow: 0 24px 80px #00000035;
  z-index: 81;
}
.ui-dialog > h2 {
  font-size: 1.6rem;
  padding-right: 32px;
