.ui-dialog > p {
  margin: 12px 0 24px;
}
.dialog-close {
  position: absolute;
  right: 10px;
  top: 10px;
}
.ui-drawer {
  top: 0;
  left: auto;
  right: 0;
  transform: none;
  height: 100dvh;
  max-height: 100dvh;
  width: min(440px, 100vw);
  border-radius: 0;
}
.ui-dialog form > .ui-button {
  margin-top: 12px;
}
.ui-accordion > div {
  border-bottom: 1px solid var(--border);
