  width: 100%;
  padding: 22px 0;
  background: none;
  border: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
}
.ui-accordion button[data-state="open"] > svg {
  transform: rotate(180deg);
}
.ui-accordion [role="region"] > div {
  padding: 0 0 22px;
  color: var(--muted-foreground);
}
.ui-tabs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  border-bottom: 1px solid var(--border);
  margin: 20px 0;
}
.ui-tabs button {
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  padding: 13px 17px;
  font-size: 0.875rem;
  color: var(--muted-foreground);
}
.ui-tabs button[data-state="active"] {
  color: var(--foreground);
  border-color: var(--primary);
  font-weight: 600;
}
.tab-panel {
  padding: 10px 0;
}
.breadcrumbs {
  list-style: none;
  display: flex;
  gap: 10px;
  font-size: 0.875rem;
}
.breadcrumbs li + li:before {
